from collections import Counter, deque

def transform(grid):
    h, w = len(grid), len(grid[0])
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    seen, comps = set(), []
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == bg or (r, c) in seen:
                continue
            q = deque([(r, c)]); seen.add((r, c)); cells = set()
            while q:
                y, x = q.popleft(); cells.add((y, x))
                for yy, xx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
                    if 0 <= yy < h and 0 <= xx < w and (yy,xx) not in seen and grid[yy][xx] == color:
                        seen.add((yy,xx)); q.append((yy,xx))
            comps.append((color, cells))
    out = [row[:] for row in grid]
    # The guide is the large L component. Select the small component in the
    # diagonal opposite the guide's two arms and recolor it with the guide color.
    guides = []
    for color, cells in comps:
        rs = [r for r,c in cells]; cs = [c for r,c in cells]
        r0,r1,c0,c1=min(rs),max(rs),min(cs),max(cs)
        if len(cells) < 6 or r1-r0 < 2 or c1-c0 < 2:
            continue
        for cr,cc in ((r0,c0),(r0,c1),(r1,c0),(r1,c1)):
            hor=sum((cr,x) in cells for x in range(c0,c1+1))
            ver=sum((y,cc) in cells for y in range(r0,r1+1))
            if hor+ver-1 >= (r1-r0+1)+(c1-c0+1)-1:
                guides.append((len(cells),color,cells,cr,cc))
    if guides:
        _, gc, guide, cr, cc=max(guides,key=lambda x:x[0])
        # If repeated congruent small motifs flank the guide, recolor the
        # lower-left copy, which is the matching continuation in this layout.
        motif_groups = {}
        for color, cells in comps:
            if cells != guide:
                r0=min(r for r,c in cells); c0=min(c for r,c in cells)
                motif_groups.setdefault(frozenset((r-r0,c-c0) for r,c in cells), []).append((color,cells))
        repeated = [g for g in motif_groups.values() if len(g)>1]
        if repeated:
            group=max(repeated,key=lambda g:len(g[0][1]))
            target=max(group,key=lambda x:max(r for r,c in x[1]))[1]
            # Recolor the later duplicate with the earlier duplicate's color.
            replacement = min(group, key=lambda x:min(r for r,c in x[1]))[0]
            for r,c in target: out[r][c]=replacement
            return out

        rdir = 1 if any(r < cr and (r,cc) in guide for r in range(cr)) else -1
        cdir = 1 if any(c < cc and (cr,c) in guide for c in range(cc)) else -1
        candidates=[]
        for color,cells in comps:
            if cells==guide: continue
            rs=[r for r,c in cells]; cs=[c for r,c in cells]
            # A candidate must lie wholly in the diagonal sector, not merely
            # have its centroid there (which admits objects touching the corner).
            row_ok = max(rs) < cr if rdir < 0 else min(rs) > cr
            col_ok = max(cs) < cc if cdir < 0 else min(cs) > cc
            if row_ok and col_ok:
                cy=sum(r for r,c in cells)/len(cells); cx=sum(c for r,c in cells)/len(cells)
                candidates.append((-(abs(cy-cr)+abs(cx-cc)),len(cells),cells))
        if candidates:
            target=min(candidates,key=lambda x:(x[0],x[1]))[2]
            for r,c in target: out[r][c]=gc
    return out

